<html lang="en">
<head>
<meta charset="utf-8">
<title>GitHub's Hottest Repos - Infographic</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: #080c1f;
    color: #e2e8f0;
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    width: 960px;
    -webkit-font-smoothing: antialiased;
  }

  #poster {
    width: 960px;
    min-height: 1480px;
    padding: 48px 44px 36px;
    background: linear-gradient(175deg, #080c1f 0%, #0d1333 35%, #0f1638 65%, #080c1f 100%);
    position: relative;
    overflow: hidden;
  }

  #poster::before {
    content: '';
    position: absolute;
    top: -120px;
    right: -120px;
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, rgba(59,130,246,0.08) 0%, transparent 70%);
    pointer-events: none;
  }

  #poster::after {
    content: '';
    position: absolute;
    bottom: -80px;
    left: -80px;
    width: 300px;
    height: 300px;
    background: radial-gradient(circle, rgba(16,185,129,0.06) 0%, transparent 70%);
    pointer-events: none;
  }

  /* ---- HEADER ---- */
  .header {
    text-align: center;
    margin-bottom: 32px;
    position: relative;
  }

  .header-badge {
    display: inline-block;
    background: linear-gradient(135deg, rgba(59,130,246,0.15), rgba(16,185,129,0.15));
    border: 1px solid rgba(59,130,246,0.3);
    border-radius: 20px;
    padding: 5px 16px;
    font-size: 11px;
    font-weight: 600;
    color: #60a5fa;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    margin-bottom: 16px;
  }

  .header h1 {
    font-size: 34px;
    font-weight: 900;
    color: #ffffff;
    letter-spacing: -1px;
    line-height: 1.15;
    margin-bottom: 10px;
  }

  .header h1 .accent {
    background: linear-gradient(135deg, #3b82f6, #10b981);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .header .subtitle {
    font-size: 15px;
    color: #94a3b8;
    font-weight: 400;
    max-width: 640px;
    margin: 0 auto;
    line-height: 1.5;
  }

  .header-line {
    height: 2px;
    background: linear-gradient(90deg, transparent, #3b82f6, #10b981, transparent);
    margin-top: 24px;
    border-radius: 1px;
  }

  /* ---- HERO METRICS ---- */
  .metrics-row {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 14px;
    margin-bottom: 28px;
  }

  .metric-card {
    background: linear-gradient(135deg, rgba(20,25,53,0.9), rgba(15,22,56,0.9));
    border: 1px solid rgba(59,130,246,0.12);
    border-radius: 12px;
    padding: 18px 14px 14px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }

  .metric-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    border-radius: 12px 12px 0 0;
  }

  .metric-card:nth-child(1)::before { background: linear-gradient(90deg, #3b82f6, #6366f1); }
  .metric-card:nth-child(2)::before { background: linear-gradient(90deg, #f59e0b, #f97316); }
  .metric-card:nth-child(3)::before { background: linear-gradient(90deg, #10b981, #06b6d4); }
  .metric-card:nth-child(4)::before { background: linear-gradient(90deg, #8b5cf6, #6366f1); }
  .metric-card:nth-child(5)::before { background: linear-gradient(90deg, #ef4444, #f97316); }

  .metric-value {
    font-size: 26px;
    font-weight: 800;
    color: #ffffff;
    font-family: 'JetBrains Mono', monospace;
    line-height: 1.1;
    margin-bottom: 6px;
  }

  .metric-card:nth-child(3) .metric-value {
    color: #10b981;
  }

  .metric-label {
    font-size: 10px;
    font-weight: 600;
    color: #94a3b8;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    line-height: 1.3;
  }

  /* ---- TABLE SECTION ---- */
  .table-section {
    margin-bottom: 24px;
  }

  .section-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 14px;
  }

  .section-title {
    font-size: 16px;
    font-weight: 700;
    color: #f1f5f9;
