    align-items: center;
    gap: 8px;
  }

  .section-title .icon {
    font-size: 18px;
  }

  .ai-badge {
    background: linear-gradient(135deg, rgba(16,185,129,0.2), rgba(59,130,246,0.2));
    border: 1px solid rgba(16,185,129,0.3);
    border-radius: 8px;
    padding: 4px 12px;
    font-size: 11px;
    font-weight: 700;
    color: #10b981;
    letter-spacing: 0.3px;
  }

  .repo-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0 3px;
  }

  .repo-table thead th {
    font-size: 10px;
    font-weight: 700;
    color: #64748b;
    text-transform: uppercase;
    letter-spacing: 1px;
    padding: 8px 10px;
    text-align: left;
    border-bottom: 1px solid rgba(100,116,139,0.2);
  }

  .repo-table thead th:nth-child(4),
  .repo-table thead th:nth-child(5) {
    text-align: right;
  }

  .repo-table tbody tr {
    background: rgba(15,20,48,0.6);
    border-radius: 8px;
    transition: background 0.15s;
  }

  .repo-table tbody tr.ai-row {
    background: rgba(16,185,129,0.05);
    border-left: 3px solid #10b981;
  }

  .repo-table tbody tr:not(.ai-row) {
    border-left: 3px solid transparent;
  }

  .repo-table tbody td {
    padding: 7px 10px;
    font-size: 12px;
    color: #cbd5e1;
    vertical-align: middle;
  }

  .repo-table tbody td:first-child {
    border-radius: 6px 0 0 6px;
    font-weight: 700;
    color: #64748b;
    width: 36px;
    text-align: center;
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
  }

  .repo-table tbody td:last-child {
