  .lang-python { background: rgba(55,118,171,0.2); color: #4da6c9; border: 1px solid rgba(55,118,171,0.3); }
  .lang-typescript { background: rgba(49,120,198,0.2); color: #5b9bd5; border: 1px solid rgba(49,120,198,0.3); }
  .lang-rust { background: rgba(222,114,56,0.2); color: #e0784a; border: 1px solid rgba(222,114,56,0.3); }
