  .lang-html { background: rgba(227,76,38,0.15); color: #e34c26; border: 1px solid rgba(227,76,38,0.3); }
  .lang-dart { background: rgba(0,180,216,0.15); color: #00b4d8; border: 1px solid rgba(0,180,216,0.3); }
  .lang-shell { background: rgba(137,221,255,0.15); color: #89ddff; border: 1px solid rgba(137,221,255,0.3); }
  .lang-verilog { background: rgba(160,120,240,0.15); color: #a078f0; border: 1px solid rgba(160,120,240,0.3); }
  .lang-none { background: rgba(100,116,139,0.15); color: #64748b; border: 1px solid rgba(100,116,139,0.3); }

  .star-val, .fork-val {
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
    font-weight: 600;
  }

  .star-val { color: #f59e0b; }
  .fork-val { color: #94a3b8; }

  .ai-indicator {
    display: inline-block;
