const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 960, height: 1500 } });

  const htmlPath = path.resolve(__dirname, 'poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle' });

  // Wait for AntV Infographic to render
  await page.waitForFunction(() => window.__chartReady === true, { timeout: 15000 }).catch(() => {});

  // Wait extra for fonts and rendering
  await page.waitForTimeout(2000);

  // Find the poster element and screenshot it
  const poster = await page.$('#poster');
  if (poster) {
    await poster.screenshot({
      path: path.resolve(__dirname, 'final_poster.png'),
      type: 'png',
    });
    console.log('Screenshot saved to final_poster.png');
  } else {
    console.error('Poster element not found');
  }

  await browser.close();
})();

