arguments.command:
node -e "
const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch({args:['--no-sandbox','--disable-gpu']});
  const p = await b.newPage({viewport:{width:960,height:1800}});
  await p.goto('file:///app/output/poster.html', {waitUntil:'networkidle'});
  await p.waitForFunction(() => window.__chartReady === true, {timeout:15000}).catch(()=>{});
  await p.waitForTimeout(2000);

  // Check chart rendered
  const chartInfo = await p.evaluate(() => {
    const c = document.querySelector('#chart-container');
    const svg = c?.querySelector('svg');
    return {
      hasSvg: !!svg,
      svgWidth: svg?.getAttribute('width'),
      svgHeight: svg?.getAttribute('height'),
      containerRect: c?.getBoundingClientRect(),
      childCount: c?.children.length
    };
  });
  console.log('Chart info:', JSON.stringify(chartInfo, null, 2));

  // Check poster total height
  const posterInfo = await p.evaluate(() => {
    const el = document.querySelector('#poster');
    return { height: el.getBoundingClientRect().height };
  });
  console.log('Poster height:', posterInfo.height);

  await b.close();
})();
" 2>&1

